package com.springbyexample.v2.structuredoutput.model;

import java.util.List;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

/**
 * Structured recommendation generated by the AI model.
 *
 * @param name             the technology name
 * @param category         the technology category
 * @param description      a description of the technology
 * @param keyFeatures      the main features
 * @param advantages       the advantages of using the technology
 * @param limitations      the limitations of the technology
 * @param suitableUseCases the use cases for which the technology is suitable
 *
 * @author Mujuzi Moses
 */
public record TechnologyRecommendation(@NotBlank String name, @NotBlank String category, @NotBlank String description,
        @NotEmpty List<@NotBlank String> keyFeatures, @NotEmpty List<@NotBlank String> advantages,
        @NotEmpty List<@NotBlank String> limitations, @NotEmpty List<@NotBlank String> suitableUseCases) {
}
